    border-style: solid;
    border-color: #ff0000;
    border-width: 1px;
}

.bold, b {
    font-weight: bold;
}

.italic, i {
    font-style: italic;
    font-size: 105%;
}

.bigtext {
    font-size: 141%
}
.smalltext {
    font-size: 85%;
}
.smallcaps {
    font-variant: small-caps
}

sup,
.superscript,
.footnoteref {
    font-size: smaller;
    vertical-align: super;
    line-height: 1;
}
.footnotebackref {
}
.footnoterule {
    margin-left: 0;
    margin-right: 75%
}

div.closer {
    font-style: italic;
}
p.center {
    text-align: center
}
p.footnote {
    font-size: smaller;
}
td {
