INSERT INTO "dpd_headwords" VALUES(4375,'anuga','anuga','adj','adj, from anugacchati','anugacchati','','','','','following; going after','','following, followed by','','anuga [anugam]','√gam','a','','anu √gam','','','','','anu + √gam + a','kita','a','','','','AN10.219','karajakāyasuttaṃ','yaṃ kho me idaṃ kiñci pubbe iminā karajakāyena pāpakammaṃ kataṃ sabbaṃ taṃ idha vedanīyaṃ, na taṃ <b>anugaṃ</b> bhavissatī''ti','SN3.20','dutiyāputtakasuttaṃ','tañ''hi tassa sakaṃ hoti,
