INSERT INTO "family_root" VALUES('√kam 2 √kam','√kam 2','√kam','desire','<p class=''heading underlined''><b>47</b> words belong to the root family <b>√kam</b> (desire)</p><table class=''family''><tr><th>akanta</th><td><b>pp</b></td><td>unpleasant; unwelcome; disagreeable</td><td><span class="gray">✔</span></td></tr><tr><th>akantiya</th><td><b>adj</b></td><td>unpleasant; unwelcome; disagreeable</td><td><span class="gray">✔</span></td></tr><tr><th>akantena</th><td><b>ind</b></td><td>not pleasingly; unpleasantly; in an undesired way</td><td><span class="gray">✔</span></td></tr><tr><th>akāma ¹</th><td><b>adj</b></td><td>without desire; without need</td><td><span class="gray">✔</span></td></tr><tr><th>akāma ²</th><td><b>adj</b></td><td>unwilling; reluctant; involuntary; without choice in the matter</td><td><span class="gray">✔</span></td></tr><tr><th>akāmaka</th><td><b>adj</b></td><td>unwilling; not wanting; reluctant</td><td><span class="gray">✔</span></td></tr><tr><th>akāmatā</th><td><b>fem</b></td><td>the state of being forced; necessarily</td><td><span class="gray">✘</span></td></tr><tr><th>akāmasā</th><td><b>ind</b></td><td>against one''s will</td><td><span class="gray">✘</span></td></tr><tr><th>akāmā</th><td><b>ind</b></td><td>unwillingly; reluctantly; involuntarily; with no choice in the matter; whether one wants to or not</td><td><span class="gray">✔</span></td></tr><tr><th>akāmita</th><td><b>pp</b></td><td>not beloved</td><td><span class="gray">✘</span></td></tr><tr><th>asakāma ¹</th><td><b>adj</b></td><td>(comm) without real pleasure (in)</td><td><span class="gray">✔</span></td></tr><tr><th>asakāma ²</th><td><b>adj</b></td><td>discontented; unsatisfied</td><td><span class="gray">✘</span></td></tr><tr><th>kanta ¹·¹</th><td><b>pp</b></td><td>charming; pleasant; desirable; agreeable (to); lit. desired</td><td><span class="gray">✔</span></td></tr><tr><th>kanta ¹·²</th><td><b>nt</b></td><td>what is desirable; what is wanted; lit. desired</td><td><span class="gray">✔