INSERT INTO "family_root" VALUES('√kar √kar','√kar','√kar','do, make','<p class=''heading underlined''><b>420</b> words belong to the root family <b>√kar</b> (do, make)</p><table class=''family''><tr><th>akaṭa ¹</th><td><b>pp</b></td><td>not done; not performed; not acted</td><td><span class="gray">✔</span></td></tr><tr><th>akaṭa ²</th><td><b>pp</b></td><td>not made; not created; unfashioned</td><td><span class="gray">✔</span></td></tr><tr><th>akaṭa ³</th><td><b>pp</b></td><td>not artificial; not prepared</td><td><span class="gray">✘</span></td></tr><tr><th>akata ¹</th><td><b>pp</b></td><td>not done; not performed; not acted</td><td><span class="gray">✔</span></td></tr><tr><th>akata ²</th><td><b>pp</b></td><td>not made; not created</td><td><span class="gray">✔</span></td></tr><tr><th>akata ³</th><td><b>nt</b></td><td>something not done; unperformed action; undone deed; lit. not done</td><td><span class="gray">✔</span></td></tr><tr><th>akata ⁴</th><td><b>pp</b></td><td>(of gold) not formed; not shaped; unwrought</td><td><span class="gray">✔</span></td></tr><tr><th>akata ⁵</th><td><b>pp</b></td><td>(of a floor) unprepared; unsealed; earthen; natural</td><td><span class="gray">✔</span></td></tr><tr><th>akatato</th><td><b>ind</b></td><td>as uncompleted; as not done</td><td><span class="gray">✔</span></td></tr><tr><th>akatatta ¹·¹</th><td><b>nt</b></td><td>fact of not having done; lit. not done state</td><td><span class="gray">✔</span></td></tr><tr><th>akatatta ¹·²</th><td><b>nt</b></td><td>fact of not having made; lit. not done state</td><td><span class="gray">✔</span></td></tr><tr><th>akattabba ¹</th><td><b>ptp</b></td><td>should not be done</td><td><span class="gray">✘</span></td></tr><tr><th>akattabba ²</th><td><b>nt</b></td><td>which should not be done; lit. not to be done</td><td><span class="gray">✔</span></td></tr><tr><th>akattha ¹</th><td><b>aor</b></td><td>you all did; you all made</td><td><span class="gray">✔</span></td></tr><tr><th>akattha ²</th><td><b>aor</b></td><td>you all made</td><td><span class="gray">✔</span></td></tr><tr><th>akatvā ¹</th><td><b>abs</b></td><td>having not done; having not performed</td><td><span class="gray">◑</span></td></tr><tr><th>akatvā ²</th><td><b>abs</b></td><td>having not made</td><td><span class="gray">◑</span></td></tr><tr><th>akatvā ³</th><td><b>abs</b></td><td>having not built; having not constructed</td><td><span class="gray">✘</span></td></tr><tr><th>akamma ¹</th><td><b>nt</b></td><td>not work; unsuitable work; criminal (for)</td><td><span class="gray">✔</span></td></tr><tr><th>akamma ²</th><td><b>nt</b></td><td>non-doing; inactivity; absence of action</td><td><span class="gray">✔</span></td></tr><tr><th>akammaka ¹</th><td><b>adj</b></td><td>having nothing to do with action</td><td><span class="gray">✘</span></td></tr><tr><th>akammaka ²</th><td><b>adj</b></td><td>(gram) intransitive; not taking an object; lit. no object</td><td><span class="gray">✔</span></td></tr><tr><th>akammañña</th><td><b>adj</b></td><td>not fit for work; not useable; not good for anything; lit. not workable</td><td><span class="gray">✔</span></td></tr><tr><th>akammaññatara</th><td><b>adj</b></td><td>less pliable; less bendable; less malleable</td><td><span class="gray">✔</span></td></tr><tr><th>akammaññatā</th><td><b>fem</b></td><td>fact (of something) not being ready for work; fact of not being fit for use; unusability; lit. not workable state</td><td><span class="gray">✔</span></td></tr><tr><th>akammaniya</th><td><b>adj</b></td><td>not ready for work; not fit for use; not functional; lit. not workable</td><td><span class="gray">✔</span></td></tr><tr><th>akammanīya</th><td><b>adj</b></td><td>not ready for work; not fit for use; not functional; lit. not workable</td><td><span class="gray">◑</span></td></tr><tr><th>akammaneyya</th><td><b>adj</b></td><td>not ready or fit for any act or use</td><td><span class="gray">✘</span></td></tr><tr><th>akayiramāna ¹</th><td><b>prp</b></td><td>not being done; not being perfo