INSERT INTO "family_root" VALUES('√kham √kham','√kham','√kham','tolerate, endure','<p class=''heading underlined''><b>53</b> words belong to the root family <b>√kham</b> (tolerate, endure)</p><table class=''family''><tr><th>akkhanti</th><td><b>fem</b></td><td>impatience; intolerance; irascibility</td><td><span class="gray">✔</span></td></tr><tr><th>akkhantī</th><td><b>adj</b></td><td>impatient; intolerant</td><td><span class="gray">✘</span></td></tr><tr><th>akkhama</th><td><b>adj</b></td><td>impatient (with); intolerant (of); not able to endure</td><td><span class="gray">✔</span></td></tr><tr><th>akkhamana</th><td><b>nt</b></td><td>intolerance; not being able to bear</td><td><span class="gray">✘</span></td></tr><tr><th>akkhamamāna</th><td><b>prp</b></td><td>not being acceptable; not being suitable; not being pleasing</td><td><span class="gray">✔</span></td></tr><tr><th>akhanti ¹</th><td><b>fem</b></td><td>impatience; discontent</td><td><span class="gray">✘</span></td></tr><tr><th>akhanti ²</th><td><b>adj</b></td><td>impatient; intolerant</td><td><span class="gray">✘</span></td></tr><tr><th>akhantiya</th><td><b>adj</b></td><td>impatient; intolerant</td><td><span class="gray">◑</span></td></tr><tr><th>akhamāpita</th><td><b>pp</b></td><td>not apologized; not asked forgiveness</td><td><span class="gray">✘</span></td></tr><tr><th>khanta</th><td><b>pp</b></td><td>patient, endured, forbore, pardoned</td><td><span class="gray">✘</span></td></tr><tr><th>khantar</th><td><b>masc</b></td><td>endurer; tolerator; bearer</td><td><span class="gray">✔</span></td></tr><tr><th>khanti ¹</th><td><b>fem</b></td><td>patience (with); endurance; tolerance (of)</td><td><span class="gray">✔</span></td></tr><tr><th>khanti ²</th><td><b>fem</b></td><td>preference; acceptance; receptivity; acquiescence</td><td><span class="gray">✔</span></td></tr><tr><th>khantika</th><td><b>adj</b></td><td>accepting; believing; agreeing</td><td><span class="gray">✔</span></td></tr><tr><th>khantimant</th><td><b>ad