INSERT INTO "family_root" VALUES('√vac √vac','√vac','√vac','say, speak','<p class=''heading underlined''><b>118</b> words belong to the root family <b>√vac</b> (say, speak)</p><table class=''family''><tr><th>anutta</th><td><b>pp</b></td><td>(gram) not mentioned; unspecified; lit. not said</td><td><span class="gray">✔</span></td></tr><tr><th>avaca ²·¹</th><td><b>imperf</b></td><td>said; told; spoke</td><td><span class="gray">✔</span></td></tr><tr><th>avacana ¹</th><td><b>nt</b></td><td>not saying; not speaking</td><td><span class="gray">✔</span></td></tr><tr><th>avacana ²</th><td><b>adj</b></td><td>speechless; dumbfounded</td><td><span class="gray">✘</span></td></tr><tr><th>avacanīya ¹</th><td><b>ptp</b></td><td>incorrigible; uninstructible; unteachable; unadmonishable; lit. not to be spoken to</td><td><span class="gray">✔</span></td></tr><tr><th>avacanīya ²</th><td><b>ptp</b></td><td>inexpressible; unspeakable</td><td><span class="gray">✘</span></td></tr><tr><th>avacaṃ</th><td><b>imperf</b></td><td>I said; I spoke</td><td><span class="gray">✔</span></td></tr><tr><th>avacāsi</th><td><b>aor</b></td><td>spoke; said (to)</td><td><span class="gray">✔</span></td></tr><tr><th>avacuttha</th><td><b>aor</b></td><td>you all said (something) (to)</td><td><span class="gray">✔</span></td></tr><tr><th>avattabbatā</th><td><b>fem</b></td><td>fact of not being able to be expressed</td><td><span class="gray">✘</span></td></tr><tr><th>avācayi</th><td><b>aor</b></td><td>caused to speak; made say</td><td><span class="gray">✘</span></td></tr><tr><th>avutta ¹</th><td><b>pp</b></td><td>not said; not spoken; not mentioned</td><td><span class="gray">✔</span></td></tr><tr><th>avutta ²</th><td><b>pp</b></td><td>(of a person) not told; not spoken to; not instructed</td><td><span class="gray">✔</span></td></tr><tr><th>avuttatā</th><td><b>fem</b></td><td>fact of not being said; fact of not being mentioned</td><td><span class="gray">◑</span></td></tr><tr><th>avuttatta</th><td><b>nt</b></td><td>fact